functions.filteredShopItems:
function(category){
 if(category!=='avatars'){
  const items=(SHOP_CATALOG[category]||[]);
  return shopRarityFilter==='all'?items:shopRarityFilter==='reward'?items.filter(x=>x.rewardOnly):items.filter(x=>x.rarity===shopRarityFilter);
 }
 const rank={common:0,uncommon:1,rare:2,epic:3,legendary:4};
 const items=mk872ModernCatalog();
 return items.filter(x=>shopRarityFilter==='all'||(shopRarityFilter==='reward'?!!x.rewardOnly:x.rarity===shopRarityFilter))
  .sort((a,b)=>(rank[a.rarity]??9)-(rank[b.rarity]??9)||Number(a.level||0)-Number(b.level||0)||Number(a.price||0)-Number(b.price||0)||a.name.localeCompare(b.name,'ru'));
}

functions.mk872CollectionOwned:
function mk872CollectionOwned(type){
 if(type==='achievements'){
  return mk872ActiveCollectionItems(type).filter(item=>isAchievementUnlocked(state,item.id));
 }
 const owned=new Set(Array.isArray(state.inventory?.[type])?state.inventory[type]:[]);
 return mk872ActiveCollectionItems(type).filter(item=>owned.has(item.id));
}

functions.mk861RollRarity:
function mk861RollRarity(pity,randomFn=mk861RandomUnit){
 const p=mk861CleanPity(pity);
 if(p.missLegendary>=MK861_LEGENDARY_MISSES_BEFORE_GUARANTEE)return "legendary";
 const r=Math.max(0,Math.min(0.9999999999999999,Number(randomFn())));
 if(p.missEpicPlus>=MK861_EPIC_PLUS_MISSES_BEFORE_GUARANTEE){
  const legendaryShare=MK861_CHEST_RATES.legendary/(MK861_CHEST_RATES.epic+MK861_CHEST_RATES.legendary);
  return r<legendaryShare?"legendary":"epic";
 }
 if(r<MK861_CHEST_RATES.rare)return "rare";
 if(r<MK861_CHEST_RATES.rare+MK861_CHEST_RATES.epic)return "epic";
 return "legendary";
}

functions.shopRarityButtons:
function shopRarityButtons(category){
 const opts=[["all","Все"],["common","Обычные"],["uncommon","Необычные"],["rare","Редкие"],["epic","Эпические"],["legendary","Легендарные"],["reward","Только награды"]];
 return `<div class="shop-filter-bar">${opts.map(([id,n])=>`<button class="shop-filter-btn ${shopRarityFilter===id?"active":""}" onclick="openShop('${category}','${id}')">${n}</button>`).join("")}</div>`;
}
